/**
 * dsh-conversation-recorder —— 记录根下的产物文档（`<root>/README.md` 与 `<root>/AGENTS.md`）。
 *
 * 为什么需要：`_conversations` 这类记录目录常被当成「素材源」交给别的 agent 或人读，
 * 但一个只装 `session-<id>/` 目录的根没有一句话说明「这是什么、怎么读、能不能改」。
 * 本模块在**首个内容轮次落盘之后**确保这两份说明存在。
 *
 * 铁规矩（SPEC §10）：
 *   · **只缺则写**：文件已存在就**一律不动**（包括没有生成标记的手写文件——那种只往 stderr 提示一行，
 *     绝不改写、绝不覆盖）；故「手写内容被机器抹掉」这件事结构上不可能发生。
 *   · 新写出的文件首行是生成标记 `<!-- generated by dsh-conversation-recorder -->`，
 *     读者一眼能分辨「机器生成」与「人写的」。
 *   · `AGENTS.md` ≤ 2KB（写前按字节数检查，超了就当写失败处理，不落盘）。
 *   · 写失败（mkdir/写/rename 任一）只往 stderr 记一行，**不抛**、不影响记录主流程。
 *   · `enabled: false` 时**一个字节都不写**（总开关语义，SPEC §8）。
 *
 * 运行时依赖：仅 node 内置 + 同插件相对模块（SPEC §9）。
 */
/** 生成标记：新产出的文档首行（读者据此分辨机器生成与人写）。 */
export declare const DOC_GENERATED_MARKER = "<!-- generated by dsh-conversation-recorder -->";
/** 产物文档文件名（记录根下）。 */
export declare const DOC_FILES: readonly ["README.md", "AGENTS.md"];
/** `AGENTS.md` 的体积上限（字节）；`README.md` 不设上限（下文也远小于它）。 */
export declare const AGENTS_MAX_BYTES = 2048;
/**
 * 记录根下的 `README.md`（面向**人**：这是什么、目录怎么排、能不能手改）。
 * 首行必须是生成标记。
 */
export declare function renderRootReadme(): string;
/**
 * 记录根下的 `AGENTS.md`（面向**读这份记录的 AI agent**：最短的用法与红线）。
 * 首行必须是生成标记；正文必须 ≤ `AGENTS_MAX_BYTES` 字节。
 */
export declare function renderRootAgents(): string;
/**
 * 确保记录根下存在 `README.md` / `AGENTS.md`（**只缺则写**）。
 *
 * @param root - 记录根目录（`_conversations` 本身）；空串直接返回（没有落点可言）
 * @param options.handwrittenHint - 缺生成标记时是否往 stderr 提示一行（默认 true）
 * @returns 本次真正**新写出**的文件名（已存在的一律不算）
 */
export declare function ensureRootDocs(root: string, options?: {
    readonly handwrittenHint?: boolean;
}): string[];
